public static double calculateAverageBalance(List<Double> closingBalances) {
    // Check if the list is null or empty
    if (closingBalances == null || closingBalances.isEmpty()) {
        throw new IllegalArgumentException("Closing balances list cannot be null or empty");
    }

    // Calculate the sum of all closing balances
    double sumOfBalances = 0;
    for (double balance : closingBalances) {
        sumOfBalances += balance;
    }

    // Calculate the average by dividing the sum by the number of closing balances
    double average = sumOfBalances / closingBalances.size();

    // Return the average account balance
    return average;
}

