public int findLargestSubstring(List<String> strings) {
    // Find the maximum length substring
    intmaxLength = 0;
    for (String str : strings) {
        if (str.length() > maxLength) maxLength = str.length();
    }

    // Check each longest substring
    for (int length = maxLength; length > 0; length--) {
        int start = 0;
        while (start + length <= maxLength) {
            String sub = str.substring(start, start + length);
            for (String other : strings) {
                if (other.contains(sub)) return length;
                // Also check the inverse substring
                if (other.contains(sub.toLowerCase())) return length;
            }
            start++;
        }
    }

    // If no substring is found, return 0
    return 0;
}

