public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String s : strings) {
        int i = 0;
        while (i < s.length()) {
            int j = s.length() - 1 - i;
            // Reverse the substring and check if it exists in the original string
            if ((i + j) % 2 == 0 && s.substring(i, j + 1).equals(new StringBuilder(s.substring(j, i + 1)).reverse().toString())) {
                maxLength = Math.max(maxLength, j + 1);
                break;
            }
            i++;
        }
    }
    return maxLength;
}

