public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (paths == null || start == null || end == null || n <= 0) {
        return "invalid input";
    }

    int rows = paths.length;
    int cols = paths[0].length;

    if (start[0] < 0 || start[1] < 0 || end[0] < 0 || end[1] < 0 || start[0] >= rows || start[1] >= cols || end[0] >= rows || end[1] >= cols) {
        return "invalid coordinates";
    }

    boolean[][] visited = new boolean[rows][cols];
    Queue<int[]> queue = new LinkedList<>();

    visited[start[0]][start[1]] = true;
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        for (int[] dir : new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
            int nx = x + dir[0];
            int ny = y + dir[1];

            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny] && paths[nx][ny] == 1) {
                visited[nx][ny] = true;
                queue.offer(new int[]{nx, ny});
            }
        }
    }

    return "cannot be travelled";
}

