public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int m = paths.length;
    if (m == 0) return "cannot be travelled";
    int src = start[0] * n + start[1];
    int dest = end[0] * n + end[1];

    boolean[] visited = new boolean[m];
    LinkedList<Integer> stack = new LinkedList<>();
    stack.push(src);

    while (!stack.isEmpty()) {
        int current = stack.pop();

        if (current == dest) return "can be travelled";

        if (visited[current]) continue;
        visited[current] = true;

        for (int next : paths[current]) {
            int destNode = next % n * n + next / n;

            if (!visited[next]) {
                stack.push(destNode);
            }
        }
    }

    return "cannot be travelled";
}

