public double trimMean(int[] arr) {
    // Sort the array
    Arrays.sort(arr);

    // Calculate the number of elements to remove from the start and end
    int discard = (arr.length * 5) / 100;

    // Skip the first discard elements and the last discard elements
    double sum = 0;
    for (int i = discard; i < arr.length - discard; i++) {
        sum += arr[i];
    }

    // Return the mean
    return sum / (arr.length - discard * 2);
}

