public String sortString(String s) {
    PriorityQueue<Character> maxQueue = new PriorityQueue<>(Collections.reverseOrder());
    PriorityQueue<Character> minQueue = new PriorityQueue<>();

    // Initialize queues with the characters of the string
    for (char c : s.toCharArray()) {
        maxQueue.offer(c);
        minQueue.offer(c);
    }

    StringBuilder result = new StringBuilder();

    // Process characters in a cycle
    while (!maxQueue.isEmpty() && !minQueue.isEmpty()) {
        // Add the smallest char
        result.append(maxQueue.poll());
        if (maxQueue.isEmpty() && !minQueue.isEmpty()) {
            result.append(minQueue.poll());
        }
        // Add the largest char
        result.append(minQueue.poll());
        if (minQueue.isEmpty() && !maxQueue.isEmpty()) {
            result.append(maxQueue.poll());
        }
    }

    return result.toString();
}

