        throw new IllegalArgumentException("Height array cannot be null or empty");
    }

    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];
    leftSmaller[0] = -1; // Starting from the left, find the nearest smaller element to the left for the first bar
    rightSmaller[heights.length - 1] = heights.length; // Starting from the right, find the nearest smaller element to the right for the last bar

    for (int i = 1; i < heights.length; i++) {
