        while (j >= 0 && heights[j] >= heights[i]) {
            j = leftSmaller[j]; // Move the pointer to the left until a smaller element is found
        }
        leftSmaller[i] = j; // Store the index of the nearest smaller element
    }

    for (int i = heights.length - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < heights.length && heights[j] >= heights[i]) {
            j = rightSmaller[j]; // Move the pointer to the right until a smaller element is found
        }
        rightSmaller[i] = j; // Store the index of the nearest smaller element
    }

    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
