public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int m = mat.length, n = mat[0].length;
    boolean leftToRight = true;
    int left = -1, up = -1;
    List<Integer> result = new ArrayList<>();

    while (result.size() < m * n) {
        int i = left + (leftToRight ? 1 : -1);
        int j = up + (leftToRight ? 0 : 1);

        while (i < m && j < n) {
            result.add(mat[i][j]);
            i += leftToRight ? 1 : -1;
            j += leftToRight ? 0 : 1;
        }

        leftToRight = !leftToRight;
        if (leftToRight) {
            left = left + m > 0 ? left + 1 : 0;
            if (left == 0 && ---up < 0) {
                break;
            }
        } else {
            up = up + n > 0 ? up + 1 : 0;
            if (up == 0 && ---left < 0) {
                break;
            }
        }
    }

    int[] resultList = new int[result.size()];
    for (int i = 0; i < result.size(); i++) {
        resultList[i] = result.get(i);
    }

    return resultList;
}

