public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }

    int size = (int) Math.pow(10, (n - 1)) / 10;
    for (int i = 0; i <= size; i++) {
        int number = i;
        int reverseNumber = 0;
        while (number > 0) {
            reverseNumber = reverseNumber * 10 + number % 10;
            number /= 10;
        }

        if (number == reverseNumber) {
            result.add(String.valueOf(reversedNumber));
        }
    }

    Collections.sort(result);
    return result;
}

