public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the area of the triangle using Heron's formula
    int s = (x2 - x1) * (y3 - y2) + (x3 - x2) * (y1 - y3);
    double area = s > 0 ? 0.5 * s : -0.5 * s;

    // Conversely, the area can also be expressed as half the cross-product of vectors AB and AC
    double crossProduct = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);

    return area != 0 && crossProduct != 0;
}

