    List<Integer> result = new ArrayList<>();
    int current = 1;
    while (current <= n) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else if (current % 10 != 9) {
            int next = current % 10 + 1;
            int nextInTen = current / 10 * 10 + next;
            current = nextInTen;
        } else {
            current /= 10;
        }
    }
    Collections.sort(result);
    return result;
}

